WITH cleaned AS (SELECT id, shipped_date, delivered_date, cost, status, CASE WHEN status IN ('RETURNED', 'LOST') THEN 'Priority' ELSE 'Other' END AS status_group FROM shipments WHERE delivered_date > DATE '2023-03-18') SELECT id, shipped_date, delivered_date, AVG(cost) OVER (PARTITION BY status ORDER BY cost, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS cost_avg_5_prior, NTILE(3) OVER (PARTITION BY status ORDER BY cost DESC, id) AS cost_bucket, LAG(cost, 1) OVER (PARTITION BY status ORDER BY cost, id) AS prev_cost FROM cleaned WHERE cost IS NOT NULL
